import React, { useState } from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { DatePicker } from './DatePicker';
import { SectionLevel } from '../empty-state';

export default {
  title: 'Data Entry/DatePicker',
  component: DatePicker,
  decorators: [
    (Story) => (
      <div style={{ height: '700px', width: '800px' }}>
        <Story />
      </div>
    ),
  ],
  parameters: {
    docs: {
      description: {
        component:
          'How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { DatePicker } from "@hexa-ui/components"`',
      },
    },
  },
} as ComponentMeta<typeof DatePicker>;

const Template: ComponentStory<typeof DatePicker> = ({
  onChange: _onChange,
  onSave: _onSave,
  value: _value,
  ...args
}) => {
  const [date, setDate] = useState<Date[]>();
  return <DatePicker width="100%" value={date} onChange={setDate} onSave={setDate} {...args} />;
};

const SideContent = () => (
  <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
    <SectionLevel description="Example of side content" />
  </div>
);

export const DefaultDatePicker = Template.bind({});
DefaultDatePicker.args = {};

